import { Injectable, Logger } from '@nestjs/common';
import Anthropic from '@anthropic-ai/sdk';
import { AiProvider } from './ai-provider.interface';
import { GeminiProvider } from './gemini.provider';
import { OpenAiProvider } from './openai.provider';

type Effort = 'low' | 'medium' | 'high' | 'xhigh' | 'max';

/**
 * Claude (Anthropic) provider.
 *
 * - Replies are generated by Claude.
 * - Claude has no embeddings API, so embeddings (used by the knowledge-base / RAG
 *   search) are delegated to Gemini or OpenAI. Keep the same embedding provider
 *   you used before, otherwise already-stored embeddings won't match new queries.
 */
@Injectable()
export class ClaudeProvider implements AiProvider {
  private readonly logger = new Logger('ClaudeProvider');
  private readonly client: Anthropic;
  private readonly defaultModel: string;
  private readonly effort: Effort;
  private readonly embeddingProvider: AiProvider | null;

  constructor() {
    this.client = new Anthropic({ apiKey: process.env.ANTHROPIC_API_KEY });
    this.defaultModel = process.env.CLAUDE_MODEL || 'claude-opus-5-5';
    // Chat-style WhatsApp replies do well at low effort (faster + cheaper).
    this.effort = (process.env.CLAUDE_EFFORT as Effort) || 'low';
    this.embeddingProvider = this.createEmbeddingProvider();
  }

  private createEmbeddingProvider(): AiProvider | null {
    const choice =
      process.env.EMBEDDING_PROVIDER ||
      (process.env.GEMINI_API_KEY
        ? 'gemini'
        : process.env.OPENAI_API_KEY
          ? 'openai'
          : '');
    if (choice === 'gemini') return new GeminiProvider();
    if (choice === 'openai') return new OpenAiProvider();
    this.logger.warn(
      'No embedding provider configured (set GEMINI_API_KEY or OPENAI_API_KEY). Knowledge-base search will not work.',
    );
    return null;
  }

  async generateReply(params: {
    systemPrompt?: string | null;
    userMessage: string;
    temperature?: number;
    maxTokens?: number;
    model: string;
  }): Promise<string | null> {
    // Agents stored in DB may still have an OpenAI/Gemini model name
    const model = params.model?.startsWith('claude-')
      ? params.model
      : this.defaultModel;

    // Thinking is always on for current Claude models and counts toward
    // max_tokens, so small caps (e.g. 10 for intent detection) would cut the
    // reply off. Keep a safe floor; reply length is steered by the prompt.
    const maxTokens = Math.max(params.maxTokens ?? 0, 8000);

    // temperature is intentionally not sent: current Claude models reject it.
    const response = await this.client.beta.messages.create({
      model,
      max_tokens: maxTokens,
      system: params.systemPrompt || 'You are a helpful WhatsApp assistant.',
      messages: [{ role: 'user', content: params.userMessage }],
      output_config: { effort: this.effort },
      // On a safety refusal, the API retries on a fallback model automatically
      betas: ['server-side-fallback-2026-07-01'],
      fallbacks: 'default',
    });

    if (response.stop_reason === 'refusal') {
      this.logger.warn(
        `Claude refused the request (${response.stop_details?.category ?? 'unknown'})`,
      );
      return null;
    }

    const text = response.content
      .filter((b): b is Anthropic.Beta.BetaTextBlock => b.type === 'text')
      .map((b) => b.text)
      .join('')
      .trim();

    return text || null;
  }

  async generateEmbedding(text: string): Promise<number[]> {
    if (!this.embeddingProvider) {
      throw new Error(
        'Embeddings are not available: Claude has no embeddings API. Set GEMINI_API_KEY or OPENAI_API_KEY.',
      );
    }
    return this.embeddingProvider.generateEmbedding(text);
  }
}
